import { formatRelative as fn, type FormatRelativeOptions } from '../format-relative.js';
import { convertToFP } from './helpers/convert-to-fp.js';
import { type FPFn3 } from './types.js';

/**
 * Curried, data-last variant of {@link formatRelative} that also accepts its options parameter (as
 * the first curried argument, i.e. the last positional argument).
 */
export const formatRelativeWithOptions: FPFn3<
  string,
  FormatRelativeOptions | undefined,
  Date,
  Date
> = convertToFP(fn, 3) as FPFn3<string, FormatRelativeOptions | undefined, Date, Date>;
